import re

def parse_duration(s):
    durations = {'h': 3600, 'm': 60, 's': 1}
    matches = re.findall(r'(\d+)s?|(\d+)h?|(\d+)m?|(\d+)s?', s)
    total_seconds = 0
    for unit, value in matches:
        if unit in durations:
            total_seconds += int(value) * durations[unit]
        else:
            total_seconds += int(value)
    return total_seconds
```

